import{_ as o,C as l,o as t,c as p,j as e,a as s,E as c,w as i,a2 as r}from"./chunks/framework.C2TvIV46.js";const y=JSON.parse('{"title":"begin","description":"","frontmatter":{},"headers":[],"relativePath":"language/elements/begin.md","filePath":"language/elements/begin.md"}'),d={name:"language/elements/begin.md"};function g(m,a,b,h,u,x){const n=l("AvailabilityCard");return t(),p("div",null,[a[1]||(a[1]=e("h1",{id:"begin",tabindex:"-1"},[s("begin "),e("a",{class:"header-anchor",href:"#begin","aria-label":'Permalink to "begin"'},"​")],-1)),c(n,{reach:"partial",halo4:"yes",h2a:"yes"},{default:i(()=>[...a[0]||(a[0]=[e("p",null,[s("The "),e("code",null,"begin"),s(" action was added in the Master Chief Collection release of Halo: Reach, it is not available on Xbox 360 versions of Halo: Reach.")],-1)])]),_:1}),a[2]||(a[2]=r(`<p>Opens an explicit <strong>sub-block</strong> inside an <a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope">action scope</a>. Although the compiler lowers <code>begin</code> to an action opcode, in source it behaves like a scope element alongside <code>condition</code>, <code>action</code>, <code>temporary</code>, and <code>or</code>.</p><p>The primary shipped use is <strong>if/elseif-style branching</strong>: several <code>begin</code>/<code>end</code> pairs in sequence, where each block has its own conditions. If a condition inside one block fails, only that block halts — the next <code>begin</code> block still runs.</p><h2 id="example-from-winter-contingency" tabindex="-1">Example from Winter Contingency <a class="header-anchor" href="#example-from-winter-contingency" aria-label="Permalink to &quot;Example from Winter Contingency&quot;">​</a></h2><p>Reach MCC&#39;s <code>tu1_winter_contingency.txt</code> rewrote a round-timeout winner check using <code>begin</code> blocks inside <code>action for_each team</code>. Each block tests a different frozen-player count and updates tie-tracking state:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">general</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">round_time_limit</span><span class="megalo-text"> </span><span class="megalo-operator">&gt;</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">timer_expired</span><span class="megalo-text"> </span><span class="megalo-variable">round_timer</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span><span class="megalo-text"> k_maximum_team_size</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">team</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players_team</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action for_each </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> active_teams_count </span><span class="megalo-operator">+=</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">team_is_active</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">begin</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">players_frozen </span><span class="megalo-operator">==</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> teams_tied </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">begin</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">players_frozen </span><span class="megalo-operator">&lt;</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players</span><span class="megalo-text"> </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">players_frozen</span></span>
<span class="line"><span class="megalo-text">			</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">least_frozen_players_team</span><span class="megalo-text"> </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Without <code>begin</code>, flat conditions would <strong>AND</strong> together — the first failing comparison would halt the rest of the iteration. Separate blocks let each branch run independently, like <code>if</code> / <code>else if</code>.</p><p>The same trigger in HREK still contains the older Reach pattern in comments: a single <code>for_each</code> body with <code>or</code>-chained conditions acting as elseif branches. MCC added the <code>begin</code> opcode (ported from Halo 4) so that logic could be expressed as explicit sub-blocks instead.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><p><code>begin</code> is written on its own line, not as <code>action begin</code>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">begin</span></span>
<span class="line"><span class="megalo-text">	[&lt;conditions, actions, temporaries, nested begin/end pairs&gt;]</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Legal contents match any other action scope: <code>condition</code>, <code>or</code>, <code>action</code>, <code>temporary</code>, and nested <code>begin</code>/<code>end</code> pairs.</p><h2 id="where-it-appears" tabindex="-1">Where it appears <a class="header-anchor" href="#where-it-appears" aria-label="Permalink to &quot;Where it appears&quot;">​</a></h2><p><code>begin</code> blocks are valid anywhere an action scope is valid:</p><ul><li>Inside a <a href="/MegaloEvolved/beta/docs/language/elements/trigger"><code>trigger</code></a> body</li><li>Inside an <code>action for_each</code> sub-trigger</li><li>Nested inside another <code>begin</code> block</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><strong>Independent blocks</strong> — Sequential <code>begin</code>/<code>end</code> pairs are evaluated one after another. A false condition inside block <em>N</em> does not prevent block <em>N + 1</em> from running.</p><p><strong>Action budget</strong> — Each <code>begin</code> line counts as <strong>one action</strong> toward the script&#39;s 1024-action limit, in addition to the actions inside the block.</p><p><strong>Temporary variables</strong> — <a href="/MegaloEvolved/beta/docs/language/variable-model#temporary-variables"><code>temporary</code></a> declarations inside a <code>begin</code> block are scoped to that block (and any nested blocks inside it).</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope">trigger — Action scope</a> — keywords valid inside triggers</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger">trigger</a> — execution and <code>for_each</code></li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition#or">Conditions — OR</a> — the pre-<code>begin</code> elseif pattern</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a> — imperative opcodes inside blocks</li><li><a href="/MegaloEvolved/beta/docs/language/variable-model#temporary-variables">Variable model — Temporary variables</a></li></ul>`,20))])}const v=o(d,[["render",g]]);export{y as __pageData,v as default};
